@pytest.mark.parametrize('fault', ['absent', 'original', 'authorization', 'foreign']) def test_wrong_capture_cannot_extend_rental_and_valid_retry_recovers(monkeypatch, fault): svc, owner, oid = booked('RENTAL') quote = extension(owner, oid) capture_id = 'absent' if fault == 'original': capture_id = money.original('RENTAL', oid)[2].money_movement_id elif fault == 'foreign': _, other_owner, other_oid = booked('RENTAL') other = extension(other_owner, other_oid) execute(other_owner, other_oid, other) with SessionLocal() as session: root = session.scalar(select(Root).where(Root.business_type == 'RENTAL_CHANGE', Root.business_id == other['quote_id'])) capture_id = session.scalar(select(Movement.money_movement_id).where( Movement.root_payment_intent_id == root.payment_intent_id, Movement.movement_type == 'CAPTURE')) original = money.capture_adjustment
def wrong_capture(*args): nonlocal capture_id if fault == 'authorization': with SessionLocal() as session: root = session.scalar(select(Root).where(Root.business_type == 'RENTAL_CHANGE', Root.business_id == quote['quote_id'])) capture_id = session.scalar(select(Movement.money_movement_id).where( Movement.root_payment_intent_id == root.payment_intent_id, Movement.movement_type == 'AUTHORIZATION')) return {'capture_id': capture_id}
monkeypatch.setattr(money, 'capture_adjustment', wrong_capture) > with pytest.raises(ValueError, match='RENTAL_CHANGE_CAPTURE_NOT_CONFIRMED'): ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E Failed: DID NOT RAISE ValueError
