@pytest.mark.parametrize('field,value', [ ('state', 'UNKNOWN'), ('currency', 'USD'), ('amount_minor', 42001), ('parent_movement_id', 'absent'), ]) def test_divergent_durable_capture_keeps_rental_pending_for_reconciliation(monkeypatch, field, value): svc, owner, oid = booked('RENTAL') quote = extension(owner, oid) original = money.capture_adjustment observed = {}
def damaged_capture(*args): result = original(*args) with SessionLocal.begin() as session: row = session.get(Movement, result['capture_id']) observed.update(id=row.money_movement_id, original=getattr(row, field)) setattr(row, field, value) return result
monkeypatch.setattr(money, 'capture_adjustment', damaged_capture) > with pytest.raises(ValueError, match='RENTAL_CHANGE_CAPTURE_NOT_CONFIRMED'): ^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^^ E Failed: DID NOT RAISE ValueError
